$ErrorActionPreference='Stop'; $base='http://localhost:3000/api'; $login=Invoke-RestMethod -Uri "$base/auth/login" -Method POST -ContentType 'application/json' -Body (@{email='admin@cerradusgelo.local';password='WiseERP@123'}|ConvertTo-Json); $h=@{Authorization="Bearer $($login.accessToken)"}; $me=Invoke-RestMethod -Uri "$base/auth/me" -Headers $h; $branchId=$me.branch.id; $stamp=Get-Date -Format 'yyyyMMddHHmmss';
$raw=Invoke-RestMethod -Uri "$base/products" -Method POST -Headers $h -ContentType 'application/json' -Body (@{name="Materia Prima PCP $stamp";sku="MP-PCP-$stamp";unit='UN';costPrice=2;salePrice=0;minimumStock=0}|ConvertTo-Json); $finished=Invoke-RestMethod -Uri "$base/products" -Method POST -Headers $h -ContentType 'application/json' -Body (@{name="Produto Acabado PCP $stamp";sku="PA-PCP-$stamp";unit='UN';costPrice=0;salePrice=10;minimumStock=0}|ConvertTo-Json);
Invoke-RestMethod -Uri "$base/inventory/entry" -Method POST -Headers $h -ContentType 'application/json' -Body (@{branchId=$branchId;productId=$raw.id;quantity=20;referenceType='PCP_TEST';notes='Carga smoke PCP'}|ConvertTo-Json)|Out-Null;
$bom=Invoke-RestMethod -Uri "$base/production/boms" -Method POST -Headers $h -ContentType 'application/json' -Body (@{productId=$finished.id;name="Ficha PCP $stamp";yieldQuantity=1;items=@(@{productId=$raw.id;quantity=2;lossPercent=0})}|ConvertTo-Json -Depth 8); $op=Invoke-RestMethod -Uri "$base/production/orders" -Method POST -Headers $h -ContentType 'application/json' -Body (@{branchId=$branchId;bomId=$bom.id;number="OP-$stamp";quantity=3}|ConvertTo-Json); Invoke-RestMethod -Uri "$base/production/orders/$($op.id)/start" -Method POST -Headers $h|Out-Null;
$rawReserved=(Invoke-RestMethod -Uri "$base/inventory?productId=$($raw.id)&branchId=$branchId" -Headers $h).data[0]; if([decimal]$rawReserved.reserved -lt 6){throw 'Reserva de matéria-prima não foi criada'}; $done=Invoke-RestMethod -Uri "$base/production/orders/$($op.id)/complete" -Method POST -Headers $h; if($done.status -ne 'COMPLETED'){throw 'OP não foi concluída'}; $rawAfter=(Invoke-RestMethod -Uri "$base/inventory?productId=$($raw.id)&branchId=$branchId" -Headers $h).data[0]; $finAfter=(Invoke-RestMethod -Uri "$base/inventory?productId=$($finished.id)&branchId=$branchId" -Headers $h).data[0]; if([decimal]$rawAfter.quantity -ne 14){throw "Saldo MP inesperado: $($rawAfter.quantity)"}; if([decimal]$rawAfter.reserved -ne 0){throw 'Reserva MP não foi liberada'}; if([decimal]$finAfter.quantity -ne 3){throw "Saldo produto acabado inesperado: $($finAfter.quantity)"}; Write-Host 'SMOKE PRODUCAO + PCP V1 CONCLUIDO COM SUCESSO.' -ForegroundColor Green
